"use client";
import {ArtemisScope} from "./artemis-scope";
import View0 from "./components/use-cases/variants/01-story-collage";
import View1 from "./components/use-cases/variants/02-role-stories";
import View2 from "./components/use-cases/variants/03-outcome-stories";
import View3 from "./components/use-cases/variants/04-scenario-rail";
import View4 from "./components/use-cases/variants/05-shader-spotlight";
const views={"story-collage":View0,"role-stories":View1,"outcome-stories":View2,"scenario-rail":View3,"shader-spotlight":View4};
export interface ArtemisUseCasesProps {className?:string;variant?:"story-collage"|"role-stories"|"outcome-stories"|"scenario-rail"|"shader-spotlight";}
export function ArtemisUseCases({className,variant="story-collage"}:ArtemisUseCasesProps){const View=views[variant];return <ArtemisScope className={`art:[&>*]:mx-auto ${className??""}`}><View/></ArtemisScope>;}
